import React from 'react';
import cx from "classnames";
import _T from './lang';

import bs from "./styles/styles.module.scss";
import "./styles/styles.scss";
import footerStyle from "./styles/footer.module.css";
import {ILang} from "./interfaces";

class Footer extends React.Component<ILang> {

    componentDidMount() {
        if(document.getElementById("reCAPTCHA")==null) {
            let reCAPTCHAScript = document.createElement('script');
            reCAPTCHAScript.id = "reCAPTCHA";
            reCAPTCHAScript.async = true;
            reCAPTCHAScript.defer = true;
            reCAPTCHAScript.type = 'text/javascript';
            reCAPTCHAScript.src = "https://recaptcha.net/recaptcha/api.js?render=6Lf1E7UUAAAAAJK2zyfMPYSjeRMFUYFE94F7pmKZ";
            document.head.appendChild(reCAPTCHAScript);
        }
    }

    render() {
        return (
            <footer
                className={cx(footerStyle["page-footer"], footerStyle["color-dark"], bs["text-center"], bs["text-md-left"], bs["pt-4"])}>
                <div className="container">
                    <div className={cx(bs["text-center"], bs["mt-3"], bs["pb-3"])}>

                    </div>
                    <div className={cx(bs["py-3"], bs["align-items-center"])} style={{"width": "100%"}}>
                        <p className={bs["text-center"]} style={{color: "lightgray"}}>
                            © 2020 - <a href="https://www.gtdev.org" target="_blank" rel="noopener noreferrer">GTDev
                            Network.</a> {_T(this.props.lang, "All rights reserved.")}<br/>
                            {this.props.lang === "en" &&
                            <span>This site is protected by reCAPTCHA and the Google <a
                                href="https://policies.google.com/privacy">Privacy Policy</a> and <a
                                href="https://policies.google.com/terms">Terms of Service</a> apply.</span>
                            }
                            {this.props.lang === "zh_CN" &&
                            <span>本网站受reCAPTCHA保护，适用Google
                                <a href="https://policies.google.com/privacy">隐私政策</a>和
                                <a href="https://policies.google.com/terms">服务条款</a>。</span>
                            }
                        </p>
                    </div>
                </div>
            </footer>
        )
    }
}

export default Footer;